import {business,options} from './business.js';
const main=document.querySelector('main'),money=n=>`$${n.toFixed(2)}`,categories=['Sedan','SUV','Sprinter'];
let path=location.pathname.replace(/\/$/,'')||'/',selected=Number(new URLSearchParams(location.search).get('option'))||0,step=0,draft={};
const button=(text,url,outline=false)=>`<a class="button ${outline?'outline':''}" href="${url}">${text} <span>↗</span></a>`;
const title=(k,h,p='')=>`<div class="page-title"><span class="eyebrow">${k}</span><h1>${h}</h1>${p?`<p>${p}</p>`:''}</div>`;
const card=(o,i)=>`<a class="fleet-card" href="/fleet/${o.category.toLowerCase()}/"><span class="number">0${i+1} / THE COLLECTION</span><h3>${o.name}</h3><div class="price">${money(o.price)} <small>/ listed 1-hour appointment</small></div><span class="arrow">↗</span></a>`;
const rates=()=>`<table class="rate-table"><thead><tr><th scope="col">SERVICE</th><th scope="col">1-HOUR LISTING</th><th scope="col">SELECT</th></tr></thead><tbody>${options.map((o,i)=>`<tr><td>${o.name}</td><td>${money(o.price)}</td><td>${button('Select',`/reserve/?option=${i}`)}</td></tr>`).join('')}</tbody></table><p class="caption">Prices and one-hour durations are supplied booking listings. Final availability, fees, taxes and transfer terms require confirmation.</p>`;
const faqs=[['How do I start a reservation?','Choose a listed service and complete your journey details. The reservation planner prepares a draft; a booking is only confirmed through the company’s booking provider.'],['What vehicle options are listed?','Luxury Sedan, Luxury SUV and Luxury Sprinter, with hourly and ATL arrival or departure listings. Specific models, capacity and amenities require confirmation.'],['Are the prices final totals?','The displayed amounts match the supplied one-hour booking listings. Taxes, additional fees, extended time and transfer pricing rules have not been verified.'],['What should I provide for airport pickup?','Include your pickup location, destination, arrival date and time, flight number, passenger count and luggage count.'],['What is the cancellation policy?','Cancellation terms and any charges must be confirmed with Martinez Logistics LLC before completing a reservation.'],['Can you accommodate accessibility or child seating requests?','Include your needs in the special requests field. Availability and suitability require confirmation before travel.']];
function home(){return `<section class="hero"><div class="entrance"><span class="eyebrow">MARTINEZ LOGISTICS LLC · CHAUFFEUR SERVICE</span><h1>The Art<br>of <em>Arriving.</em></h1><p>Professional chauffeur transportation,<br>thoughtfully arranged around your journey.</p><div class="actions">${button('Reserve Your Ride','/reserve/')}${button('Explore Our Fleet','/fleet/',true)}</div></div><div class="hero-bottom"><span><b>01 —</b> &nbsp; EVERY JOURNEY DESERVES AN ENTRANCE</span><span>DISCOVER MORE &nbsp; ↓</span></div></section><section class="intro"><div><span class="eyebrow">A MORE CONSIDERED WAY TO TRAVEL</span><h2>Transportation,<br><em>Elevated.</em></h2></div><div><p>From an ATL airport transfer to time reserved for your plans, choose the chauffeur service that fits your journey. Explore three luxury vehicle categories and arrange the details in one considered experience.</p><a class="text-link" href="/about/">Discover Martinez &nbsp; ↗</a><p class="caption">Hero imagery is illustrative. Actual vehicle models and amenities are subject to confirmation.</p></div></section><section class="section"><div class="section-head"><div><span class="eyebrow">THE COLLECTION</span><h2>A class for every arrival.</h2></div><a class="text-link" href="/fleet/">Enter the private showroom &nbsp; ↗</a></div><div class="fleet-grid">${options.slice(0,3).map(card).join('')}</div></section><section class="section"><span class="eyebrow">AT YOUR SERVICE</span><h2>Your journey. Your pace.</h2>${[['01','Airport Transfers','Arrival and departure options for ATL, across all three vehicle categories.','airport-transfers'],['02','Hourly Chauffeur','A one-hour listing for your choice of luxury sedan, SUV or Sprinter.','hourly-chauffeur']].map(a=>`<a class="service-row" href="/services/${a[3]}/"><span class="num">${a[0]}</span><h3>${a[1]}</h3><p>${a[2]}</p><span>↗</span></a>`).join('')}</section><section class="section"><span class="eyebrow">A SEAMLESS START</span><h2>Make it your journey.</h2><div class="steps">${[['01','Choose your service','Explore the vehicle categories and listed ATL transfer options.'],['02','Arrange the details','Add your journey, date, time and passenger requirements.'],['03','Review your plans','Review the listed rate and prepare your reservation details for confirmation.']].map(a=>`<div><b>${a[0]}</b><h3>${a[1]}</h3><p>${a[2]}</p></div>`).join('')}</div></section><section class="final-cta"><span class="eyebrow">THE NEXT CHAPTER</span><h2>Your next arrival<br>begins here.</h2><p>Set the details. Let the journey take shape.</p>${button('Plan Your Journey','/reserve/')}</section>`}
function fleet(){let c=path.split('/')[2],idx=Math.max(0,categories.findIndex(x=>x.toLowerCase()===c));return `<div class="page">${title('THE PRIVATE SHOWROOM','A considered collection.','Choose a category. Discover the listed services. Make it your journey.')}<div class="showroom"><div class="showroom-scene"><span class="caption">Illustrative SUV image · Actual fleet photography pending</span></div><div><span class="eyebrow">EXPLORE THE COLLECTION</span><div class="selector">${categories.map((x,i)=>`<button data-category="${i}" aria-pressed="${i===idx}">${x}</button>`).join('')}</div><div id="vehicle"></div><p class="caption">Model, passenger capacity, luggage capacity and amenities require confirmation. Accurate fleet photos and licensed 3D assets have not been supplied.</p></div></div><section>${rates()}</section></div>`}
function showVehicle(i){const o=options[i];document.querySelectorAll('[data-category]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.category)===i));document.querySelector('#vehicle').innerHTML=`<h2>${o.name}</h2><p>Listed one-hour appointment · ${money(o.price)}</p>${button('Select This Category',`/reserve/?option=${i}`)}`}
const escape=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
function reserve(){selected=Math.min(options.length-1,Math.max(0,selected));return `<div class="page"><div class="booking"><aside class="booking-aside"><span class="eyebrow">YOUR PRIVATE RESERVATION PLANNER</span><h2>Your journey,<br>thoughtfully arranged.</h2><div class="showroom-scene"><span class="caption">Illustrative category imagery</span></div><h3 id="selection-name">${options[selected].name}</h3><p id="selection-price">${money(options[selected].price)} · listed 1-hour appointment</p><div class="notice">This planner prepares a reservation draft. Live availability and booking submission are awaiting the company’s booking connection. No reservation or payment is confirmed here.</div></aside><section><div class="progress" aria-label="Reservation progress">${['JOURNEY','DATE & TIME','PASSENGERS','REVIEW'].map((x,i)=>`<span data-progress="${i}">${i+1} ${x}</span>`).join('')}</div><form id="booking-form"></form></section></div></div>`}
function renderStep(){document.querySelectorAll('[data-progress]').forEach(x=>x.classList.toggle('active',Number(x.dataset.progress)===step));let f=document.querySelector('#booking-form');let today=new Intl.DateTimeFormat('en-CA',{timeZone:business.timezone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
let html=step===0?`<span class="eyebrow">01 / YOUR JOURNEY</span><h3>Where shall we take you?</h3><label>Service<select name="option">${options.map((o,i)=>`<option value="${i}" ${i===selected?'selected':''}>${o.name} — ${money(o.price)}</option>`).join('')}</select></label><label>Pickup location<input name="pickup" required maxlength="300" autocomplete="street-address" value="${escape(draft.pickup)}"></label><label>Destination<input name="destination" required maxlength="300" value="${escape(draft.destination)}"></label><div class="two"><label>Passengers<input name="passengers" type="number" min="1" max="99" required value="${escape(draft.passengers||1)}"></label><label>Luggage pieces<input name="luggage" type="number" min="0" max="99" required value="${escape(draft.luggage||0)}"></label></div><p class="caption">Vehicle capacity will need confirmation for your party and luggage.</p>`:step===1?`<span class="eyebrow">02 / DATE & TIME</span><h3>A time for your plans.</h3><label>Travel date<input type="date" name="date" min="${today}" value="${escape(draft.date)}" required></label><label>Pickup time · Eastern Time<input type="time" name="time" value="${escape(draft.time)}" required></label>${options[selected].type==='Arrival'?`<label>Flight number<input name="flight" maxlength="30" value="${escape(draft.flight)}" required></label><label>Terminal / pickup notes<input name="terminal" value="${escape(draft.terminal)}" maxlength="200"></label>`:''}<p class="caption">Times use America/New_York. Operating hours, lead times and availability require confirmation.</p>`:step===2?`<span class="eyebrow">03 / PASSENGER DETAILS</span><h3>The details that matter.</h3><label>Full name<input name="name" autocomplete="name" value="${escape(draft.name)}" maxlength="120" required></label><label>Email<input name="email" type="email" autocomplete="email" value="${escape(draft.email)}" maxlength="200" required></label><label>Phone<input name="phone" type="tel" autocomplete="tel" value="${escape(draft.phone)}" maxlength="40" required></label><label>Special requests<textarea name="notes" maxlength="2000">${escape(draft.notes)}</textarea></label><p class="caption">Requests are subject to confirmation. Details stay in this page’s memory and are cleared when you reload or leave.</p>`:`<span class="eyebrow">04 / REVIEW YOUR JOURNEY</span><h3>Every detail, considered.</h3><dl class="review">${[['Service',options[selected].name],['Listed 1-hour rate',money(options[selected].price)],['Pickup',draft.pickup],['Destination',draft.destination],['Date & time',`${draft.date} · ${draft.time} Eastern Time`],['Party',`${draft.passengers} passengers · ${draft.luggage} luggage pieces`],['Flight',draft.flight||'Not provided'],['Passenger',`${draft.name} · ${draft.email} · ${draft.phone}`],['Special requests',draft.notes||'None']].map(([k,v])=>`<dt>${k}</dt><dd>${escape(v)}</dd>`).join('')}</dl><div class="notice">This is a draft, not a submitted request. Final pricing, availability and policies must be confirmed. Download the details to keep your plans.</div>`;
f.innerHTML=html+`<p class="error" role="alert" id="form-error"></p><div class="actions">${step>0?'<button class="button outline" type="button" id="back">Back</button>':''}<button class="button" type="submit">${step===3?'Download Journey Draft':'Continue'} <span>${step===3?'↓':'→'}</span></button></div>`;
f.querySelector('#back')?.addEventListener('click',()=>{capture();step--;history.pushState({step},'');renderStep()});f.querySelector('[name=option]')?.addEventListener('change',e=>{selected=Number(e.target.value);document.querySelector('#selection-name').textContent=options[selected].name;document.querySelector('#selection-price').textContent=`${money(options[selected].price)} · listed 1-hour appointment`});f.onsubmit=e=>{e.preventDefault();capture();if(step===1){const now=new Date();const local=new Intl.DateTimeFormat('sv-SE',{timeZone:business.timezone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(now).replace(' ','T');if(`${draft.date}T${draft.time}`<=local){document.querySelector('#form-error').textContent='Please select a future date and time in Eastern Time.';return}}if(step<3){step++;history.pushState({step},'');renderStep()}else{const content=`MARTINEZ LOGISTICS LLC\nRESERVATION DRAFT — NOT SUBMITTED OR CONFIRMED\n\n${options[selected].name}\nListed 1-hour rate: ${money(options[selected].price)}\nFinal fees and availability require confirmation.\n\n`+Object.entries(draft).filter(([k])=>k!=='option').map(([k,v])=>`${k}: ${v}`).join('\n');const u=URL.createObjectURL(new Blob([content],{type:'text/plain'})),a=document.createElement('a');a.href=u;a.download='martinez-journey-draft.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}};f.querySelector('h3')?.setAttribute('tabindex','-1');if(step)f.querySelector('h3')?.focus({preventScroll:true})}
function capture(){for(const [k,v] of new FormData(document.querySelector('#booking-form')))draft[k]=v}
function services(){const airport=path.includes('airport-transfers'),hourly=path.includes('hourly-chauffeur');return `<div class="page">${title('SIGNATURE SERVICES',airport?'The airport, effortlessly.':hourly?'Time, on your terms.':'Arranged around you.',airport?'Explore the supplied ATL arrival and departure transfer listings.':hourly?'Choose a one-hour listing for your luxury vehicle category.':'Hourly chauffeur options and ATL transfers, with a choice of sedan, SUV or Sprinter.')}<div class="actions">${button('ATL Airport Transfers','/services/airport-transfers/',!airport)}${button('Hourly Chauffeur','/services/hourly-chauffeur/',!hourly)}</div>${rates()}</div>`}
function informational(){let content={
'/about':['OUR STORY','The care is in the journey.','Martinez Logistics LLC offers chauffeur service, with supplied listings for luxury sedans, SUVs and Sprinters. The collection includes hourly appointments and ATL arrival and departure transfers.','Explore the collection and prepare your travel details. Specific vehicles, amenities and availability should be confirmed before booking.'],
'/service-areas':['SERVICE AREAS','An ATL connection.','ATL arrival and departure transfers are included in the supplied booking options.','Additional service areas have not yet been verified. Confirm your pickup and destination with the company before making travel arrangements.'],
'/contact':['GET IN TOUCH','Let’s arrange your arrival.','Start with your vehicle category, travel date, pickup location and destination.','Verified company phone, email and booking-provider details are awaiting configuration. Use the journey planner to prepare a draft. It does not send an inquiry.'],
'/privacy':['PRIVACY','Your details, considered.','This preview collects journey details only in page memory. It does not send them to Martinez Logistics LLC or store them in browser storage. A downloaded draft is saved to your own device.','Hosting and external font providers may process standard technical connection data. An approved business privacy policy is required before enabling live inquiry or booking submission.'],
'/terms':['TERMS','Before your journey.','The supplied rates describe one-hour booking listings. They are not a verified final quote or a guarantee of availability. This site’s planner does not confirm a booking or collect payment.','Cancellation, additional time, taxes, surcharges, service boundaries and other business policies require confirmation. Approved company terms must be added before accepting live reservations.']};let a=content[path];return `<div class="page">${title(a[0],a[1],a[2])}<p>${a[3]}</p><div class="actions">${button('Plan Your Journey','/reserve/')}${button('Explore Our Fleet','/fleet/',true)}</div></div>`}
if(path==='/')main.innerHTML=home();else if(path.startsWith('/fleet')){main.innerHTML=fleet();showVehicle(Math.max(0,categories.findIndex(x=>path.endsWith(x.toLowerCase()))));document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>showVehicle(Number(b.dataset.category)))}else if(path==='/reserve'){main.innerHTML=reserve();renderStep();addEventListener('popstate',e=>{capture();step=e.state?.step||0;renderStep()})}else if(path.startsWith('/services'))main.innerHTML=services();else if(path==='/faq')main.innerHTML=`<div class="page">${title('FREQUENTLY ASKED','A few useful details.')}<div class="faq">${faqs.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></div>`;else if(['/about','/contact','/privacy','/terms','/service-areas'].includes(path))main.innerHTML=informational();else main.innerHTML=`<div class="page">${title('404','A different destination.','This page could not be found.')}${button('Return Home','/')}</div>`;
if(path!=='/'){const heading=main.querySelector('h1')?.textContent||'Reservations';document.title=`${heading} | Martinez Logistics LLC`}document.querySelector('#year').textContent=new Date().getFullYear();document.querySelector('.menu').onclick=e=>{let open=document.querySelector('nav').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',open)};document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelector('nav').classList.remove('open');document.querySelector('.menu').setAttribute('aria-expanded','false')}});
const ld=document.createElement('script');ld.type='application/ld+json';ld.textContent=JSON.stringify({'@context':'https://schema.org','@type':'Organization',name:business.name,url:business.origin,logo:business.origin+'/assets/logo.png'});document.head.append(ld);
